 let last=performance.now();(function loop(){requestAnimationFrame(loop);const now=performance.now(),dt=Math.min(0.05,(now-last)/1000);last=now;if(V.mx)V.mx.update(dt);if(V.H)animHuman(V.H,dt,0,now/1000,false);if(V.spin&&V.o)V.o.rotation.y+=dt;
  const t=V.size;CAM.position.set(Math.sin(V.yaw)*V.dist*t,(0.9+0.5*V.dist/4.2)*t,Math.cos(V.yaw)*V.dist*t);CAM.lookAt(0,0.7*t,0);if(TAB==='terrain'&&TV3.on){if(TV3.need){TV3.need=false;tv3Cam();R.render(TV3.sc,TV3.cam);}}else if(!mapTab()&&!PICK)R.render(SC,CAM);})();
 /* ---------- les types de fiches ---------- */
